local ped = {}addEvent("doLALearnKampfartClient", true)addEvent("doLAKampfartFail", true)ped["lerner"] = createPed(203, 765.05999755859, -78.669631958008, 1000.65625)addEventHandler("onClientPedDamage", ped["lerner"], cancelEvent)setElementFrozen(ped["lerner"], true)setElementInterior(ped["lerner"], 7)local lernmarker = createMarker(765.03973388672, -77.918937683105, 999.65625, "cylinder", 1.0, 0, 255, 0, 50)setElementInterior(lernmarker, 7)local ped1 = createPed(81, 774.13812255859, -66.536987304688, 1000.6580810547, 92)local ped2 = createPed(80, 773.19329833984, -66.45263671875, 1000.6597290039, 269)addEventHandler("onClientPedDamage", ped1, cancelEvent)setElementFrozen(ped1, true)setElementInterior(ped1, 7)addEventHandler("onClientPedDamage", ped2, cancelEvent)setElementFrozen(ped2, true)setElementInterior(ped2, 7)if(math.random(0, 1) == 1) then	setPedAnimation(ped1, "ped" , "IDLE_chat", -1, true, false, false)else	setPedAnimation(ped2, "ped" , "IDLE_chat", -1, true, false, false)endlocal Guivar = 0local Fenster = {}local Knopf = {}local Label = {}local Radio = {}local function createKampfartGui()	if(Guivar == 1) then return end	Guivar = 1	showCursor(true)	local X, Y, Width, Height = getMiddleGuiPosition(270,238)	Fenster[1] = guiCreateWindow(X, Y, Width, Height, "Kampfarten",false)	Label[1] = guiCreateLabel(11,22,236,18,"Welche Kampfart möchten Sie erlernen?",false,Fenster[1])	guiSetFont(Label[1],"default-bold-small")	Radio[1] = guiCreateRadioButton(14,53,82,20,"Standard",false,Fenster[1])	guiSetFont(Radio[1],"default-bold-small")	Radio[2] = guiCreateRadioButton(14,75,82,20,"Boxen",false,Fenster[1])	guiSetFont(Radio[2],"default-bold-small")	Radio[3] = guiCreateRadioButton(14,98,82,20,"Kung-Fu",false,Fenster[1])	guiSetFont(Radio[3],"default-bold-small")	Radio[4] = guiCreateRadioButton(14,121,82,20,"Streetfight",false,Fenster[1])	guiSetFont(Radio[4],"default-bold-small")	Radio[5] = guiCreateRadioButton(14,145,82,20,"Grab-Kick",false,Fenster[1])	guiSetFont(Radio[5],"default-bold-small")	Radio[6] = guiCreateRadioButton(14,168,82,20,"Ellenbogen",false,Fenster[1])	guiSetFont(Radio[6],"default-bold-small")	Knopf[1] = guiCreateButton(13,197,112,31,"OK",false,Fenster[1])	Knopf[2] = guiCreateButton(139,196,112,31,"Abbrechen",false,Fenster[1])		addEventHandler("onClientGUIClick", Knopf[2], function()		Guivar = 0		destroyElement(Fenster[1])		showCursor(false)	end, false)		addEventHandler("onClientGUIClick", Knopf[1], function()		local art = 0		for i = 1, #Radio, 1 do			if(guiRadioButtonGetSelected(Radio[i]) == true) then				art = i				break;			end		end		if(art == 0) then			outputChatBox("Bitte wähle eine Kampfart aus!", 255, 0, 0)			return		end		triggerServerEvent("doLALearnKampfart", localPlayer, art)		Guivar = 0		destroyElement(Fenster[1])		showCursor(false)	end, false)endaddEventHandler("onClientMarkerHit", lernmarker, function(h)	if(h == localPlayer) then		createKampfartGui()	endend)-- AI --local pedTarget = {}local pedTimer = {}local pedShooting = {}local dim = 0local function doPedAttackOtherPlayer(ped)	if(isTimer(pedTimer[ped])) or (isPedInVehicle(ped)) then		killTimer(pedTimer[ped])	end	if(isElement(ped)) then		pedTimer[ped] = setTimer(function()			if(isElement(ped)) then				local target = pedTarget[ped]				if(target) then					local x, y, z = getElementPosition(ped)					local x2, y2, z2 = getElementPosition(target)					if(getDistanceBetweenPoints3D(x, y, z, x2, y2, z2) < 2) then						setPedAnimation(ped)						if(isLineOfSightClear(x, y, z, x2, y2, z2, true, false, false, false, false, false)) then							if(getElementHealth(target) > 1) then								if(pedShooting[ped] ~= true) then									--[[									local x1, y1 = getElementPosition(ped)									local x2, y2 = getElementPosition(target)										local rot = math.atan2(y2 - y1, x2 - x1) * 180 / math.pi										rot = rot-90										setPedRotation(ped, rot)										setPedAnimation(ped)										if(getPedControlState(ped, "fire") ~= true) then											setPedControlState(ped, "fire", true)										end										setPedAimTarget(ped, x2, y2, z2)]]									setPedControlState(ped, "fire", true)									pedShooting[ped] = true								else									local x1, y1, z1 = getElementPosition(ped)									local x2, y2, z2 = getElementPosition(target)									local rot = math.atan2(y2 - y1, x2 - x1) * 180 / math.pi									rot = rot-90									setPedRotation(ped, rot)									setPedAimTarget(ped, x2, y2, z2)									setPedControlState(ped, "fire", false)									pedShooting[ped] = false								end							else								killTimer(pedTimer[ped])								pedShooting[ped] = false								setPedControlState(ped, "fire", false)							end						else							killTimer(pedTimer[ped])							pedShooting[ped] = false							setPedControlState(ped, "fire", false)						end					else						local x1, y1, z1 = getElementPosition(ped)						local x2, y2, z2 = getElementPosition(target)						local rot = math.atan2(y2 - y1, x2 - x1) * 180 / math.pi						rot = rot-90						setPedRotation(ped, rot)						local block, anim = getPedAnimation(ped)						if(block == "ped") and (anim == "JOG_maleA") then else							setPedAnimation(ped, "ped" , "JOG_maleA", -1, true, true, false) -- Joggt							setPedControlState(ped, "fire", false)							pedShooting[ped] = false						end					end				end			else				killTimer(pedTimer[ped])			end		end, 250, -1)	else		killTimer(pedTimer[ped])	endendlocal art = 0local function finishPed(art)	fadeCamera(false)	setTimer(function()		destroyElement(ped["attacker"])		triggerServerEvent("doLALearnKampfartFinish", localPlayer, art)		for i = 1, 3, 1 do			destroyElement(ped["zuschauer"..i])		end	end, 1500, 1)	toggleAllControls(true)endlocal function setToAttackingPed()	ped["attacker"] = createPed(204, 766.81469726563, -71.088623046875, 1001.569152832, 0)	pedTarget[ped["attacker"]] = localPlayer	doPedAttackOtherPlayer(ped["attacker"])	setElementDimension(ped["attacker"], dim)	setElementInterior(ped["attacker"], getElementInterior(localPlayer))	addEventHandler("onClientPedWasted", ped["attacker"], finishPed)	setElementHealth(ped["attacker"], 200)endlocal random_skins = {	[1] = 80,	[2] = 81,	[3] = 204,	[4] = 203}local rand_animations = {	[1] = "COP_AMBIENT, Coplook_shake",	[2] = "RAPPING, RAP_C_Loop",}local function createZuschauer()	local randskin = random_skins[math.random(1, #random_skins)]	ped["zuschauer1"] = createPed(randskin, 761.56219482422, -67.001274108887, 1000.5853271484, 256)		local randskin = random_skins[math.random(1, #random_skins)]	ped["zuschauer2"] = createPed(randskin, 761.83032226563, -70.900108337402, 1000.65625, 297)		local randskin = random_skins[math.random(1, #random_skins)]	ped["zuschauer3"] = createPed(randskin, 766.23889160156, -73.627532958984, 1000.65625, 357)		setElementDimension(ped["zuschauer1"], dim)	setElementDimension(ped["zuschauer2"], dim)	setElementDimension(ped["zuschauer3"], dim)	setElementInterior(ped["zuschauer1"], getElementInterior(localPlayer))	setElementInterior(ped["zuschauer2"], getElementInterior(localPlayer))	setElementInterior(ped["zuschauer3"], getElementInterior(localPlayer))		setPedAnimation(ped["zuschauer1"], "COP_AMBIENT", "Coplook_shake")	setPedAnimation(ped["zuschauer2"], "COP_AMBIENT", "Coplook_shake")	setPedAnimation(ped["zuschauer3"], "RAPPING", "RAP_C_Loop")endaddEventHandler("doLALearnKampfartClient", getLocalPlayer(), function(art2)	dim = getElementDimension(localPlayer)	setToAttackingPed()	createZuschauer()	art = art2end)addEventHandler("doLAKampfartFail", getLocalPlayer(), function()	destroyElement(ped["attacker"])	for i = 1, 3, 1 do		destroyElement(ped["zuschauer"..i])	end	toggleAllControls(true)end)